#include <iostream>
#include <vector>
#include <algorithm>
#include <functional>
#include <climits>

using namespace std;

struct Point {
    int x, y;
};

int main() {
    int N;
    cin >> N;
    vector<Point> mackerels;
    vector<Point> sardines;
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        mackerels.push_back({x, y});
    }
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        sardines.push_back({x, y});
    }

    // Sort mackerels by x, then by y
    sort(mackerels.begin(), mackerels.end(), [](const Point& a, const Point& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });
    // Sort sardines similarly
    sort(sardines.begin(), sardines.end(), [](const Point& a, const Point& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    // Compute B_m
    int x_min_m = mackerels[0].x;
    int x_max_m = mackerels[0].x;
    int y_min_m = mackerels[0].y;
    int y_max_m = mackerels[0].y;
    for (const auto& p : mackerels) {
        x_min_m = min(x_min_m, p.x);
        x_max_m = max(x_max_m, p.x);
        y_min_m = min(y_min_m, p.y);
        y_max_m = max(y_max_m, p.y);
    }

    // Count sardines in B_m
    int sardines_in_Bm = 0;
    vector<Point> sardines_in_Bm_list;
    for (const auto& s : sardines) {
        if (s.x >= x_min_m && s.x <= x_max_m && s.y >= y_min_m && s.y <= y_max_m) {
            sardines_in_Bm++;
            sardines_in_Bm_list.push_back(s);
        }
    }

    if (sardines_in_Bm == 0) {
        cout << 4 << endl;
        cout << x_min_m << " " << y_min_m << endl;
        cout << x_max_m << " " << y_min_m << endl;
        cout << x_max_m << " " << y_max_m << endl;
        cout << x_min_m << " " << y_max_m << endl;
        return 0;
    }

    int best_diff = -1;
    int best_xmin = x_min_m;
    int best_xmax = x_max_m;
    int best_ymin = y_min_m;
    int best_ymax = y_max_m;

    auto count_mackerels = [&](int x1, int x2, int y1, int y2) -> int {
        int cnt = 0;
        auto left = lower_bound(mackerels.begin(), mackerels.end(), Point{x1, 0}, 
            [](const Point& a, const Point& b) { return a.x < b.x; });
        auto right = upper_bound(mackerels.begin(), mackerels.end(), Point{x2, INT_MAX}, 
            [](const Point& a, const Point& b) { return a.x < b.x; });
        for (auto it = left; it != right; ++it) {
            if (it->y >= y1 && it->y <= y2) {
                cnt++;
            }
        }
        return cnt;
    };

    auto count_sardines = [&](int x1, int x2, int y1, int y2) -> int {
        int cnt = 0;
        auto left = lower_bound(sardines.begin(), sardines.end(), Point{x1, 0}, 
            [](const Point& a, const Point& b) { return a.x < b.x; });
        auto right = upper_bound(sardines.begin(), sardines.end(), Point{x2, INT_MAX}, 
            [](const Point& a, const Point& b) { return a.x < b.x; });
        for (auto it = left; it != right; ++it) {
            if (it->y >= y1 && it->y <= y2) {
                cnt++;
            }
        }
        return cnt;
    };

    for (const auto& s : sardines_in_Bm_list) {
        // Adjust x_min to exclude s.x
        int new_xmin = s.x + 1;
        int new_xmax = x_max_m;
        if (new_xmin <= new_xmax) {
            int a = count_mackerels(new_xmin, new_xmax, y_min_m, y_max_m);
            int b = count_sardines(new_xmin, new_xmax, y_min_m, y_max_m);
            int diff = a - b;
            if (diff > best_diff) {
                best_diff = diff;
                best_xmin = new_xmin;
                best_xmax = new_xmax;
                best_ymin = y_min_m;
                best_ymax = y_max_m;
            }
        }

        // Adjust x_max to exclude s.x
        int new_xmax_s = s.x - 1;
        int new_xmin_s = x_min_m;
        if (new_xmin_s <= new_xmax_s) {
            int a = count_mackerels(new_xmin_s, new_xmax_s, y_min_m, y_max_m);
            int b = count_sardines(new_xmin_s, new_xmax_s, y_min_m, y_max_m);
            int diff = a - b;
            if (diff > best_diff) {
                best_diff = diff;
                best_xmin = new_xmin_s;
                best_xmax = new_xmax_s;
                best_ymin = y_min_m;
                best_ymax = y_max_m;
            }
        }

        // Adjust y_min to exclude s.y
        int new_ymin = s.y + 1;
        int new_ymax = y_max_m;
        if (new_ymin <= new_ymax) {
            int a = count_mackerels(x_min_m, x_max_m, new_ymin, new_ymax);
            int b = count_sardines(x_min_m, x_max_m, new_ymin, new_ymax);
            int diff = a - b;
            if (diff > best_diff) {
                best_diff = diff;
                best_xmin = x_min_m;
                best_xmax = x_max_m;
                best_ymin = new_ymin;
                best_ymax = new_ymax;
            }
        }

        // Adjust y_max to exclude s.y
        int new_ymax_s = s.y - 1;
        int new_ymin_s = y_min_m;
        if (new_ymin_s <= new_ymax_s) {
            int a = count_mackerels(x_min_m, x_max_m, new_ymin_s, new_ymax_s);
            int b = count_sardines(x_min_m, x_max_m, new_ymin_s, new_ymax_s);
            int diff = a - b;
            if (diff > best_diff) {
                best_diff = diff;
                best_xmin = x_min_m;
                best_xmax = x_max_m;
                best_ymin = new_ymin_s;
                best_ymax = new_ymax_s;
            }
        }
    }

    // Compute original_diff
    int original_a = count_mackerels(x_min_m, x_max_m, y_min_m, y_max_m);
    int original_b = count_sardines(x_min_m, x_max_m, y_min_m, y_max_m);
    int original_diff = original_a - original_b;
    if (original_diff > best_diff) {
        best_diff = original_diff;
        best_xmin = x_min_m;
        best_xmax = x_max_m;
        best_ymin = y_min_m;
        best_ymax = y_max_m;
    }

    cout << 4 << endl;
    cout << best_xmin << " " << best_ymin << endl;
    cout << best_xmax << " " << best_ymin << endl;
    cout << best_xmax << " " << best_ymax << endl;
    cout << best_xmin << " " << best_ymax << endl;
