#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int N;
    cin >> N;

    vector<pair<int, int>> mackerels, sardines;
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        mackerels.emplace_back(x, y);
    }
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        sardines.emplace_back(x, y);
    }

    // Compute initial box for mackerels
    int x_min_m = mackerels[0].first;
    int x_max_m = mackerels[0].first;
    int y_min_m = mackerels[0].second;
    int y_max_m = mackerels[0].second;
    for (const auto& p : mackerels) {
        x_min_m = min(x_min_m, p.first);
        x_max_m = max(x_max_m, p.first);
        y_min_m = min(y_min_m, p.second);
        y_max_m = max(y_max_m, p.second);
    }

    // Check for sardines in initial box
    vector<pair<int, int>> conflict_sardines;
    for (const auto& s : sardines) {
        int x = s.first;
        int y = s.second;
        if (x_min_m <= x && x <= x_max_m && y_min_m <= y && y <= y_max_m) {
            conflict_sardines.push_back(s);
        }
    }

    if (conflict_sardines.empty()) {
        // Output initial box
        cout << 4 << endl;
        cout << x_min_m << " " << y_min_m << endl;
        cout << x_min_m << " " << y_max_m << endl;
        cout << x_max_m << " " << y_max_m << endl;
        cout << x_max_m << " " << y_min_m << endl;
        return 0;
    }

    // Generate candidates
    vector<vector<int>> candidates;
    // Add initial box
    vector<int> initial_box = {x_min_m, x_max_m, y_min_m, y_max_m};
    candidates.push_back(initial_box);

    for (const auto& s : conflict_sardines) {
        int xs = s.first;
        int ys = s.second;

        // Adjust x_min
        int new_x1 = xs + 1;
        int new_x2 = x_max_m;
        if (new_x1 <= new_x2) {
            vector<int> box = {new_x1, new_x2, y_min_m, y_max_m};
            candidates.push_back(box);
        }

        // Adjust x_max
        int new_x2_adj = xs - 1;
        int new_x1_adj = x_min_m;
        if (new_x2_adj >= new_x1_adj) {
            vector<int> box = {new_x1_adj, new_x2_adj, y_min_m, y_max_m};
            candidates.push_back(box);
        }

        // Adjust y_min
        int new_y1 = ys + 1;
        int new_y2 = y_max_m;
        if (new_y1 <= new_y2) {
            vector<int> box = {x_min_m, x_max_m, new_y1, new_y2};
            candidates.push_back(box);
        }

        // Adjust y_max
        int new_y2_adj = ys - 1;
        int new_y1_adj = y_min_m;
        if (new_y2_adj >= new_y1_adj) {
            vector<int> box = {x_min_m, x_max_m, new_y1_adj, new_y2_adj};
            candidates.push_back(box);
        }
    }

    // Now evaluate all candidates
    int best_val = -1;
    vector<int> best_box;

    for (const auto& box : candidates) {
        int x1 = box[0], x2 = box[1], y1 = box[2], y2 = box[3];

        // Count mackerels
        int a = 0;
        for (const auto& p : mackerels) {
            if (x1 <= p.first && p.first <= x2 && y1 <= p.second && p.second <= y2) {
                a++;
            }
        }

        // Count sardines
        int b = 0;
        for (const auto& s : sardines) {
            if (x1 <= s.first && s.first <= x2 && y1 <= s.second && s.second <= y2) {
                b++;
            }
        }

        int current_val = a - b;
        if (current_val > best_val) {
            best_val = current_val;
            best_box = box;
        }
    }

    // Output best_box
    int x1 = best_box[0], x2 = best_box[1], y1 = best_box[2], y2 = best_box[3];

    cout << 4 << endl;
    cout << x1 << " " << y1 << endl;
    cout << x1 << " " << y2 << endl;
    cout << x2 << " " << y2 << endl;
    cout << x2 << " " << y1 << endl;
    return 0;
}

