using namespace std;

int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> mackerels, sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Compute initial bounding box for mackerels
    int x_min_m = mackerels[0].first;
    int x_max_m = mackerels[0].first;
    int y_min_m = mackerels[0].second;
    int y_max_m = mackerels[0].second;

    for (auto& p : mackerels) {
        x_min_m = min(x_min_m, p.first);
        x_max_m = max(x_max_m, p.first);
        y_min_m = min(y_min_m, p.second);
        y_max_m = max(y_max_m, p.second);
    }

    // Check for sardines inside the initial box
    vector<pair<int, int>> sardines_in_initial;
    for (auto& s : sardines) {
        int sx = s.first;
        int sy = s.second;
        if (sx >= x_min_m && sx <= x_max_m && sy >= y_min_m && sy <= y_max_m) {
            sardines_in_initial.push_back(s);
        }
    }

    // Preprocess mackerel x and y coordinates for binary search
    vector<int> m_x;
    vector<int> m_y;
    for (auto& p : mackerels) {
        m_x.push_back(p.first);
        m_y.push_back(p.second);
    }
    sort(m_x.begin(), m_x.end());
    sort(m_y.begin(), m_y.end());

    vector<tuple<int, int, int, int>> candidates;

    // Add initial rectangle as a candidate
    int width_initial = x_max_m - x_min_m;
    int height_initial = y_max_m - y_min_m;
    if (2 * (width_initial + height_initial) <= 400000) {
        candidates.push_back({x_min_m, x_max_m, y_min_m, y_max_m});
    }

    // Generate additional candidates by excluding each sardine in initial box
    for (auto& s : sardines_in_initial) {
        int sx = s.first;
        int sy = s.second;

        // Try adjusting x boundaries
        auto it_x = lower_bound(m_x.begin(), m_x.end(), sx);
        int pos_x = it_x - m_x.begin();
        if (pos_x > 0) {
            int max_x_less = m_x[pos_x - 1];
            candidates.push_back({x_min_m, max_x_less, y_min_m, y_max_m});
        }
        if (pos_x < m_x.size()) {
            int min_x_greater = m_x[pos_x];
            candidates.push_back({min_x_greater, x_max_m, y_min_m, y_max_m});
        }

        // Try adjusting y boundaries
        auto it_y = lower_bound(m_y.begin(), m_y.end(), sy);
        int pos_y = it_y - m_y.begin();
        if (pos_y > 0) {
            int max_y_less = m_y[pos_y - 1];
            candidates.push_back({x_min_m, x_max_m, y_min_m, max_y_less});
        }
        if (pos_y < m_y.size()) {
            int min_y_greater = m_y[pos_y];
            candidates.push_back({x_min_m, x_max_m, min_y_greater, y_max_m});
        }
    }

    // Evaluate all candidates
    int best_score_val = -1e9;
    vector<tuple<int, int, int, int>> best_candidates;

    for (auto& cand : candidates) {
        int x_min_c = get<0>(cand);
        int x_max_c = get<1>(cand);
        int y_min_c = get<2>(cand);
        int y_max_c = get<3>(cand);

        // Check if valid rectangle
        if (x_max_c < x_min_c || y_max_c < y_min_c) continue;

        int width = x_max_c - x_min_c;
        int height = y_max_c - y_min_c;
        if (2 * (width + height) > 400000) continue;

        int cnt_m = 0, cnt_s = 0;
        for (auto& p : mackerels) {
            if (p.first >= x_min_c && p.first <= x_max_c && p.second >= y_min_c && p.second <= y_max_c) {
                ++cnt_m;
            }
        }
        for (auto& s : sardines) {
            if (s.first >= x_min_c && s.first <= x_max_c && s.second >= y_min_c && s.second <= y_max_c) {
                ++cnt_s;
            }
        }

        double current_score = cnt_m - cnt_s;
        if (current_score > best_score_val) {
            best_score_val = current_score;
            best_candidates.clear();
            best_candidates.push_back(cand);
        } else if (current_score == best_score_val) {
            best_candidates.push_back(cand);
        }
    }

    // Choose the best candidate
    if (best_candidates.empty()) {
        // Fallback to initial box if no valid candidates found
        if (width_initial >= 0 && height_initial >= 0 && 2 * (width_initial + height_initial) <= 400000) {
            candidates.push_back({x_min_m, x_max_m, y_min_m, y_max_m});
            best_candidates = candidates;
        }
    }

    auto best_cand = best_candidates[0];
    int x_min_c = get<0>(best_cand);
    int x_max_c = get<1>(best_cand);
    int y_min_c = get<2>(best_cand);
    int y_max_c = get<3>(best_cand);

    cout << 4 << endl;
    cout << x_min_c << " " << y_min_c << endl;
    cout << x_max_c << " " << y_min_c << endl;
    cout << x_max_c << " " << y_max_c << endl;
    cout << x_min_c << " " << y_max_c << endl;
    return 0;
}

