    vector<pair<int, int>> mackerels;
    vector<pair<int, int>> sardines;
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        mackerels.push_back({x, y});
    }
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        sardines.push_back({x, y});
    }

    vector<Rect> candidates;

    // Candidate 1: bounding box of all mackerels
    int min_mx = mackerels[0].first;
    int max_mx = mackerels[0].first;
    int min_my = mackerels[0].second;
    int max_my = mackerels[0].second;
    for (auto p : mackerels) {
        if (p.first < min_mx) min_mx = p.first;
        if (p.first > max_mx) max_mx = p.first;
        if (p.second < min_my) min_my = p.second;
        if (p.second > max_my) max_my = p.second;
    }
    int w = max_mx - min_mx;
    int h = max_my - min_my;
    int perimeter = 2 * (w + h);
    if (perimeter <= 400000 && w > 0 && h > 0) {
        candidates.push_back({ min_mx, min_my, max_mx, max_my });
    }

    // Candidate 2: pairs from first 100 mackerels
    const int K = 100;
    for (int i = 0; i < K && i < N; ++i) {
        for (int j = i + 1; j < K && j < N; ++j) {
            int x1 = mackerels[i].first;
            int y1 = mackerels[i].second;
            int x2 = mackerels[j].first;
            int y2 = mackerels[j].second;
            int min_x = min(x1, x2);
            int max_x = max(x1, x2);
            int min_y = min(y1, y2);
            int max_y = max(y1, y2);
            int w = max_x - min_x;
            int h = max_y - min_y;
            int perimeter = 2 * (w + h);
            if (perimeter <= 400000 && w > 0 && h > 0) {
                candidates.push_back({ min_x, min_y, max_x, max_y });
            }
        }
    }

    // Now, find the best candidate
    int best_diff = -1;
    Rect best_rect;
    for (auto rect : candidates) {
        int count_m = 0;
        int count_s = 0;
        for (auto p : mackerels) {
            if (p.first >= rect.min_x && p.first <= rect.max_x && p.second >= rect.min_y && p.second <= rect.max_y) {
                count_m++;
            }
        }
        for (auto p : sardines) {
            if (p.first >= rect.min_x && p.first <= rect.max_x && p.second >= rect.min_y && p.second <= rect.max_y) {
                count_s++;
            }
        }
        int current_diff = count_m - count_s;
        if (current_diff > best_diff) {
            best_diff = current_diff;
            best_rect = rect;
        }
    }

    // Output the best_rect
    if (!candidates.empty()) {
        cout << 4 << endl;
        cout << best_rect.min_x << " " << best_rect.min_y << endl;
        cout << best_rect.max_x << " " << best_rect.min_y << endl;
        cout << best_rect.max_x << " " << best_rect.max_y << endl;
        cout << best_rect.min_x << " " << best_rect.max_y << endl;
    } else {
        // fallback: output a small rectangle
        cout << 4 << endl;
        cout << 0 << " " << 0 << endl;
        cout << 1 << " " << 0 << endl;
        cout << 1 << " " << 1 << endl;
        cout << 0 << " " << 1 << endl;
    }

    return 0;
}

