#include <bits/stdc++.h>
using namespace std;

struct Point {
    int x, y;
    bool is_mackerel;
    Point(int _x, int _y, bool _is) : x(_x), y(_y), is_mackerel(_is) {}
};

int main() {
    int N;
    cin >> N;
    vector<Point> all_points;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        bool is_mackerel = (i < N);
        all_points.emplace_back(x, y, is_mackerel);
    }

    // Sort all points by x, then by y
    sort(all_points.begin(), all_points.end(), [](const Point &a, const Point &b) {
        if (a.x != b.x) return a.x < b.x;
        return a.y < b.y;
    });

    // Step 1: Kadane's algorithm on x
    vector<int> contrib_x;
    for (const auto &p : all_points) {
        contrib_x.push_back(p.is_mackerel ? 1 : -1);
    }

    int x_start = 0, x_end = 0;
    int max_x_sum = -1e9;
    int current_sum = 0;
    int temp_start = 0;
    for (int i = 0; i < contrib_x.size(); ++i) {
        if (current_sum + contrib_x[i] > contrib_x[i]) {
            current_sum += contrib_x[i];
        } else {
            current_sum = contrib_x[i];
            temp_start = i;
        }
        if (current_sum > max_x_sum) {
            max_x_sum = current_sum;
            x_start = temp_start;
            x_end = i;
        }
    }

    // Now, extract the x_subarray
    vector<Point> x_subarray(all_points.begin() + x_start, all_points.begin() + x_end + 1);

    // Step 2: sort by y and apply Kadane's algorithm on y
    sort(x_subarray.begin(), x_subarray.end(), [](const Point &a, const Point &b) {
        if (a.y != b.y) return a.y < b.y;
        return a.x < b.x;
    });

    vector<int> contrib_y;
    for (const auto &p : x_subarray) {
        contrib_y.push_back(p.is_mackerel ? 1 : -1);
    }

    int y_start = 0, y_end = 0;
    int max_y_sum = -1e9;
    current_sum = 0;
    temp_start = 0;
    for (int i = 0; i < contrib_y.size(); ++i) {
        if (current_sum + contrib_y[i] > contrib_y[i]) {
            current_sum += contrib_y[i];
        } else {
            current_sum = contrib_y[i];
            temp_start = i;
        }
        if (current_sum > max_y_sum) {
            max_y_sum = current_sum;
            y_start = temp_start;
            y_end = i;
        }
    }

    // Now, get the x_min, x_max, y_min, y_max
    int x_min = all_points[x_start].x;
    int x_max = all_points[x_end].x;
    int y_min = x_subarray[y_start].y;
    int y_max = x_subarray[y_end].y;

    // Check if x_min == x_max or y_min == y_max
    if (x_min == x_max || y_min == y_max) {
        // Expand x
        if (x_min == x_max) {
            // Find the next x in x_subarray that is different
            int new_x = x_min;
            for (auto &p : x_subarray) {
                if (p.x != x_min) {
                    new_x = p.x;
                    break;
                }
            }
            if (new_x == x_min) {
                new_x = x_min + 1;
            }
            x_max = new_x;
        }
        // Expand y
        if (y_min == y_max) {
            int new_y = y_min;
            for (auto &p : x_subarray) {
                if (p.y != y_min) {
                    new_y = p.y;
                    break;
                }
            }
            if (new_y == y_min) {
                new_y = y_min + 1;
            }
            y_max = new_y;
        }
    }

    // Output the rectangle
    cout << 4 << endl;
    cout << x_min << " " << y_min << endl;
    cout << x_max << " " << y_min << endl;
    cout << x_max << " " << y_max << endl;
    cout << x_min << " " << y_max << endl;

    return 0;
}

#include <bits/stdc++.h>
