int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> mackerels;
    vector<pair<int, int>> sardines;
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        mackerels.push_back({x, y});
    }
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        sardines.push_back({x, y});
    }

    // Compute initial rectangle for mackerels
    int xlow_m = INT_MAX, xhigh_m = INT_MIN;
    int ylow_m = INT_MAX, yhigh_m = INT_MIN;
    for (const auto& p : mackerels) {
        xlow_m = min(xlow_m, p.first);
        xhigh_m = max(xhigh_m, p.first);
        ylow_m = min(ylow_m, p.second);
        yhigh_m = max(yhigh_m, p.second);
    }

    // Count sardines in initial rectangle
    int count_s = 0;
    for (const auto& p : sardines) {
        if (p.first >= xlow_m && p.first <= xhigh_m && p.second >= ylow_m && p.second <= yhigh_m) {
            count_s++;
        }
    }

    if (count_s == 0) {
        cout << 4 << endl;
        cout << xlow_m << " " << ylow_m << endl;
        cout << xhigh_m << " " << ylow_m << endl;
        cout << xhigh_m << " " << yhigh_m << endl;
        cout << xlow_m << " " << yhigh_m << endl;
        return 0;
    }

    int best_score = 0;
    int best_xlow = xlow_m, best_xhigh = xhigh_m;
    int best_ylow = ylow_m, best_yhigh = yhigh_m;

    vector<pair<int, int>> s_in_rect;
    for (const auto& p : sardines) {
        if (p.first >= xlow_m && p.first <= xhigh_m && p.second >= ylow_m && p.second <= yhigh_m) {
            s_in_rect.push_back(p);
        }
    }

    for (const auto& s : s_in_rect) {
        int sx = s.first, sy = s.second;

        vector<vector<int>> candidates;
        // New_rect1: xlow to sx-1
        if (sx - 1 >= xlow_m) {
            candidates.push_back({xlow_m, sx - 1, ylow_m, yhigh_m});
        }
        // New_rect2: sx+1 to xhigh
        if (sx + 1 <= xhigh_m) {
            candidates.push_back({sx + 1, xhigh_m, ylow_m, yhigh_m});
        }
        // New_rect3: ylow to sy-1
        if (sy - 1 >= ylow_m) {
            candidates.push_back({xlow_m, xhigh_m, ylow_m, sy - 1});
        }
        // New_rect4: sy+1 to yhigh
        if (sy + 1 <= yhigh_m) {
            candidates.push_back({xlow_m, xhigh_m, sy + 1, yhigh_m});
        }

        for (const auto& candidate : candidates) {
            int cxlow = candidate[0], cxhigh = candidate[1];
            int cylow = candidate[2], cyhigh = candidate[3];

            // Count mackerels in this rectangle
            int a = 0;
            for (const auto& p : mackerels) {
                if (p.first >= cxlow && p.first <= cxhigh && p.second >= cylow && p.second <= cyhigh) {
                    a++;
                }
            }

            // Count sardines in this rectangle
            int b = 0;
            for (const auto& p : sardines) {
                if (p.first >= cxlow && p.first <= cxhigh && p.second >= cylow && p.second <= cyhigh) {
                    b++;
                }
            }

            int current_score = a - b;
            if (current_score > best_score) {
                best_score = current_score;
                best_xlow = cxlow;
                best_xhigh = cxhigh;
                best_ylow = cylow;
                best_yhigh = cyhigh;
            }
        }
    }

    // Also consider the initial rectangle
    int initial_score = N - count_s;
    if (initial_score > best_score) {
        best_score = initial_score;
        best_xlow = xlow_m;
        best_xhigh = xhigh_m;
        best_ylow = ylow_m;
        best_yhigh = yhigh_m;
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << best_xlow << " " << best_ylow << endl;
