#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>
using namespace std;

vector<pair<int, int>> mackerels;
vector<pair<int, int>> sardines;

int count_points_in_rect(const vector<pair<int, int>>& points, int x_low, int x_high, int y_low, int y_high) {
    int count = 0;
    for (const auto& p : points) {
        if (p.first >= x_low && p.first <= x_high && p.second >= y_low && p.second <= y_high) {
            ++count;
        }
    }
    return count;
}

int main() {
    int N;
    cin >> N;
    mackerels.resize(N);
    sardines.resize(N);
    for (int i = 0; i < 2*N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels[i] = {x, y};
        } else {
            sardines[i - N] = {x, y};
        }
    }

    // Initial rectangle for mackerels
    int min_x_m = numeric_limits<int>::max();
    int max_x_m = numeric_limits<int>::min();
    int min_y_m = numeric_limits<int>::max();
    int max_y_m = numeric_limits<int>::min();

    for (const auto& p : mackerels) {
        min_x_m = min(min_x_m, p.first);
        max_x_m = max(max_x_m, p.first);
        min_y_m = min(min_y_m, p.second);
        max_y_m = max(max_y_m, p.second);
    }

    int best_x_low = min_x_m;
    int best_x_high = max_x_m;
    int best_y_low = min_y_m;
    int best_y_high = max_y_m;
    int best_score = N - count_points_in_rect(sardines, best_x_low, best_x_high, best_y_low, best_y_high);

    // Check if initial rectangle is valid
    if (best_x_low >= best_x_high || best_y_low >= best_y_high) {
        // Need to adjust to valid rectangle
        int delta = 1;
        int new_x_low, new_x_high;
        int new_y_low, new_y_high;
        // Try expanding x range
        new_x_low = best_x_low - delta;
        new_x_high = best_x_high + delta;
        if (new_x_low < new_x_high) {
            best_x_low = new_x_low;
            best_x_high = new_x_high;
            best_y_low = best_y_low;
            best_y_high = best_y_high;
        } else {
            // Try expanding y range
            new_y_low = best_y_low - delta;
            new_y_high = best_y_high + delta;
            best_y_low = new_y_low;
            best_y_high = new_y_high;
            best_x_low = best_x_low;
            best_x_high = best_x_high;
        }
    }

    // Now, process each sardine to find better rectangle
    for (int i = 0; i < N; ++i) {
        auto s = sardines[i];
        int s_x = s.first;
        int s_y = s.second;

        // Case 1: adjust x_high to s.x - 1
        int new_x_high = s_x - 1;
        if (new_x_high > best_x_low) {
            int a = count_points_in_rect(mackerels, best_x_low, new_x_high, best_y_low, best_y_high);
            int b = count_points_in_rect(sardines, best_x_low, new_x_high, best_y_low, best_y_high);
            int current_score = a - b;
            if (current_score > best_score) {
                best_score = current_score;
                best_x_high = new_x_high;
            }
        }

        // Case 2: adjust x_low to s.x + 1
        int new_x_low = s_x + 1;
        if (new_x_low < best_x_high) {
            int a = count_points_in_rect(mackerels, new_x_low, best_x_high, best_y_low, best_y_high);
            int b = count_points_in_rect(sardines, new_x_low, best_x_high, best_y_low, best_y_high);
            int current_score = a - b;
            if (current_score > best_score) {
                best_score = current_score;
                best_x_low = new_x_low;
            }
        }

        // Case 3: adjust y_high to s.y - 1
        int new_y_high = s_y - 1;
        if (new_y_high > best_y_low) {
            int a = count_points_in_rect(mackerels, best_x_low, best_x_high, best_y_low, new_y_high);
            int b = count_points_in_rect(sardines, best_x_low, best_x_high, best_y_low, new_y_high);
            int current_score = a - b;
            if (current_score > best_score) {
                best_score = current_score;
                best_y_high = new_y_high;
            }
        }

        // Case 4: adjust y_low to s.y + 1
        int new_y_low = s_y + 1;
        if (new_y_low < best_y_high) {
            int a = count_points_in_rect(mackerels, best_x_low, best_x_high, new_y_low, best_y_high);
            int b = count_points_in_rect(sardines, best_x_low, best_x_high, new_y_low, best_y_high);
            int current_score = a - b;
            if (current_score > best_score) {
                best_score = current_score;
                best_y_low = new_y_low;
            }
        }
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << best_x_low << " " << best_y_low << endl;
    cout << best_x_high << " " << best_y_low << endl;
    cout << best_x_high << " " << best_y_high << endl;
    cout << best_x_low << " " << best_y_high << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using pii = pair<int, int>;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int N;
    cin >> N;
    vector<pii> mackerels;
    vector<pii> sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Compute initial rectangle
    int x_min_m = mackerels[0].first;
    int x_max_m = mackerels[0].first;
    int y_min_m = mackerels[0].second;
    int y_max_m = mackerels[0].second;
    for (const auto& p : mackerels) {
        if (p.first < x_min_m) x_min_m = p.first;
        if (p.first > x_max_m) x_max_m = p.first;
        if (p.second < y_min_m) y_min_m = p.second;
        if (p.second > y_max_m) y_max_m = p.second;
    }

    // Function to count points inside rectangle
    auto countInside = [&](const vector<pii>& points, int x1, int x2, int y1, int y2) {
        int cnt = 0;
        for (const auto& p : points) {
            if (p.first >= x1 && p.first <= x2 && p.second >= y1 && p.second <= y2) {
                cnt++;
            }
        }
        return cnt;
    };

    int best_a = N;
    int best_b = countInside(sardines, x_min_m, x_max_m, y_min_m, y_max_m);
    int best_score = best_a - best_b;
    int best_x1 = x_min_m, best_x2 = x_max_m, best_y1 = y_min_m, best_y2 = y_max_m;

    // Generate other candidates
    for (const auto& s : sardines) {
        int s_x = s.first;
        int s_y = s.second;
        // Check if s is inside the initial rectangle
        if (s_x >= x_min_m && s_x <= x_max_m && s_y >= y_min_m && s_y <= y_max_m) {
            // Case 1: adjust x_right to s.x - 1
            int new_x2 = s_x - 1;
            if (new_x2 > x_min_m) {
                int current_a = countInside(mackerels, x_min_m, new_x2, y_min_m, y_max_m);
                int current_b = countInside(sardines, x_min_m, new_x2, y_min_m, y_max_m);
                int current_score = current_a - current_b;
                if (current_score > best_score) {
                    best_score = current_score;
                    best_x1 = x_min_m;
                    best_x2 = new_x2;
                    best_y1 = y_min_m;
                    best_y2 = y_max_m;
                }
            }

            // Case 2: adjust x_left to s.x + 1
            int new_x1 = s_x + 1;
            if (new_x1 < x_max_m) {
                int current_a = countInside(mackerels, new_x1, x_max_m, y_min_m, y_max_m);
                int current_b = countInside(sardines, new_x1, x_max_m, y_min_m, y_max_m);
                int current_score = current_a - current_b;
                if (current_score > best_score) {
                    best_score = current_score;
                    best_x1 = new_x1;
                    best_x2 = x_max_m;
                    best_y1 = y_min_m;
                    best_y2 = y_max_m;
                }
            }

            // Case 3: adjust y_top to s.y - 1
            int new_y2 = s_y - 1;
            if (new_y2 > y_min_m) {
                int current_a = countInside(mackerels, x_min_m, x_max_m, y_min_m, new_y2);
                int current_b = countInside(sardines, x_min_m, x_max_m, y_min_m, new_y2);
                int current_score = current_a - current_b;
                if (current_score > best_score) {
                    best_score = current_score;
                    best_x1 = x_min_m;
                    best_x2 = x_max_m;
                    best_y1 = y_min_m;
                    best_y2 = new_y2;
                }
            }

            // Case 4: adjust y_bottom to s.y + 1
            int new_y1 = s_y + 1;
            if (new_y1 < y_max_m) {
                int current_a = countInside(mackerels, x_min_m, x_max_m, new_y1, y_max_m);
                int current_b = countInside(sardines, x_min_m, x_max_m, new_y1, y_max_m);
                int current_score = current_a - current_b;
                if (current_score > best_score) {
                    best_score = current_score;
                    best_x1 = x_min_m;
                    best_x2 = x_max_m;
                    best_y1 = new_y1;
                    best_y2 = y_max_m;
                }
            }
        }
    }

    // Ensure the best rectangle is valid
    if (best_x1 >= best_x2 || best_y1 >= best_y2) {
        best_x1 = x_min_m;
        best_x2 = x_max_m;
        best_y1 = y_min_m;
        best_y2 = y_max_m;
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << best_x1 << " " << best_y1 << endl;
    cout << best_x2 << " " << best_y1 << endl;
    cout << best_x2 << " " << best_y2 << endl;
    cout << best_x1 << " " << best_y2 << endl;

    return 0;
}
